import{_ as A,C as s,o as e,c as d,a6 as r,b as i,w as t,a as E,E as n,a7 as o}from"./chunks/framework.BBIckNDn.js";const D=JSON.parse('{"title":"グラフィックスAPIの歴史","description":"","frontmatter":{"title":"グラフィックスAPIの歴史","study":{"source":"RenderingWiki","kind":"本文","status":"既存原稿","summary":"グラフィックスAPIはアプリケーションとGPUドライバの間の契約です。30年の歴史は「抽象度を上げてきた前半」と「抽象を剥がして明示化した後半」に分かれます。この転換の物語を理解すると、DX12/Vulkanの一見不可解な複雑さが「すべて必然だった」と分かります。"}},"headers":[],"relativePath":"graphics/api/history.md","filePath":"graphics/api/history.md"}'),h={name:"graphics/api/history.md"};function u(B,a,c,p,P,m){const l=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="グラフィックスapiの歴史" tabindex="-1">グラフィックスAPIの歴史 <a class="header-anchor" href="#グラフィックスapiの歴史" aria-label="Permalink to &quot;グラフィックスAPIの歴史&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>グラフィックスAPIは<strong>アプリケーションとGPUドライバの間の契約</strong>です。30年の歴史は「抽象度を上げてきた前半」と「抽象を剥がして明示化した後半」に分かれます。この転換の物語を理解すると、DX12/Vulkanの一見不可解な複雑さが「すべて必然だった」と分かります。</p><h2 id="なぜ必要なのか" tabindex="-1">なぜ必要なのか <a class="header-anchor" href="#なぜ必要なのか" aria-label="Permalink to &quot;なぜ必要なのか&quot;">​</a></h2><ul><li>APIの設計思想を知らずに使うと、「なぜ手動でバリアを張るのか」「なぜPSOがあるのか」が暗記になってしまう</li><li>旧APIの限界を知ることは、新APIの正しい使い方 (マルチスレッド記録、事前コンパイル) の理解に直結する</li></ul><h2 id="年表" tabindex="-1">年表 <a class="header-anchor" href="#年表" aria-label="Permalink to &quot;年表&quot;">​</a></h2>',6)),(e(),i(o,null,{default:t(()=>[n(l,{id:"mermaid-27",class:"mermaid",graph:"timeline%0A%20%20%20%20title%20%E3%82%B0%E3%83%A9%E3%83%95%E3%82%A3%E3%83%83%E3%82%AF%E3%82%B9API%E9%80%B2%E5%8C%96%E5%8F%B2%0A%20%20%20%201992%20%3A%20OpenGL%201.0%20(SGI%20%E3%83%AF%E3%83%BC%E3%82%AF%E3%82%B9%E3%83%86%E3%83%BC%E3%82%B7%E3%83%A7%E3%83%B3%E3%81%8B%E3%82%89)%0A%20%20%20%201995-96%20%3A%20DirectX%201%E3%80%9C3%20%2F%20Direct3D%20%E5%88%9D%E7%89%88%20(Windows%E3%82%B2%E3%83%BC%E3%83%A0%E5%B8%82%E5%A0%B4%E7%8D%B2%E5%BE%97%E6%88%A6%E7%95%A5)%0A%20%20%20%201996%20%3A%203dfx%20Glide%20(Voodoo%E5%B0%82%E7%94%A8%E3%83%BB%E4%BA%8B%E5%AE%9F%E4%B8%8A%E3%81%AE%E6%A8%99%E6%BA%96%E3%81%AB)%0A%20%20%20%201999-2002%20%3A%20DX7%20(T%26L)%20%E2%86%92%20DX8%20(%E3%82%B7%E3%82%A7%E3%83%BC%E3%83%80)%20%E2%86%92%20DX9%20(SM2.0%2C%20%E9%95%B7%E6%9C%9F%E6%94%BF%E6%A8%A9)%0A%20%20%20%202006-08%20%3A%20DX10%20(%E5%AE%8C%E5%85%A8%E5%86%8D%E8%A8%AD%E8%A8%88%E3%83%BBVista%E5%B0%82%E7%94%A8)%20%2F%20OpenGL%203.0%20(%E5%88%B7%E6%96%B0%E5%A4%B1%E6%95%97)%0A%20%20%20%202009%20%3A%20DX11%20(Compute%2C%20%E5%A4%9A%E3%82%B9%E3%83%AC%E3%83%83%E3%83%89%E6%8F%8F%E7%94%BB%E3%81%AE%E8%A9%A6%E3%81%BF)%0A%20%20%20%202013%20%3A%20AMD%20Mantle%20(%E6%98%8E%E7%A4%BA%E7%9A%84API%E3%81%AE%E5%AE%9F%E8%A8%BC)%0A%20%20%20%202014%20%3A%20Apple%20Metal%20(%E3%83%A2%E3%83%90%E3%82%A4%E3%83%AB%E5%88%9D%E3%81%AE%E6%98%8E%E7%A4%BA%E7%9A%84API)%0A%20%20%20%202015%20%3A%20DirectX%2012%20(Windows%2010)%0A%20%20%20%202016%20%3A%20Vulkan%201.0%20(Mantle%E7%9B%B4%E7%B3%BB%E3%83%BBKhronos)%0A%20%20%20%202018%20%3A%20DXR%20(%E3%83%AC%E3%82%A4%E3%83%88%E3%83%AC%E3%83%BC%E3%82%B7%E3%83%B3%E3%82%B0)%20%2F%20Turing%0A%20%20%20%202023%20%3A%20WebGPU%201.0%20(Web%E6%A8%99%E6%BA%96%E3%81%AE%E6%98%8E%E7%A4%BA%E7%9A%84API)%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="第1期-群雄割拠-1992〜1998" tabindex="-1">第1期: 群雄割拠 (1992〜1998) <a class="header-anchor" href="#第1期-群雄割拠-1992〜1998" aria-label="Permalink to &quot;第1期: 群雄割拠 (1992〜1998)&quot;">​</a></h2><ul><li><strong>OpenGL</strong> (1992): SGIのIRIS GLを標準化。ワークステーションCAD/科学可視化が出自。ステートマシンモデル、<code>glBegin/glEnd</code> の即時モード</li><li><strong>Direct3D</strong> (1996): MicrosoftがWindowsゲーム市場のために買収 (RenderMorphics) して構築。初期は評判が悪く、Carmackの「D3Dは使い物にならない」批判 (1996) が有名</li><li><strong>Glide</strong> (1996): 3dfx Voodoo専用の薄いAPI。ハードに直結し高速 — <strong>「薄いAPIは速い」という後の明示的APIの原点的教訓</strong></li><li>この時代の課題: API乱立、ドライバ品質のばらつき、固定機能の制約</li></ul><h2 id="第2期-directxの覇権とプログラマブル化-1999〜2008" tabindex="-1">第2期: DirectXの覇権とプログラマブル化 (1999〜2008) <a class="header-anchor" href="#第2期-directxの覇権とプログラマブル化-1999〜2008" aria-label="Permalink to &quot;第2期: DirectXの覇権とプログラマブル化 (1999〜2008)&quot;">​</a></h2><ul><li>DX7 (1999) でT&amp;L対応、<strong>DX8 (2000) でシェーダ導入</strong>、DX9 (2002) が長期の業界標準に (XPと共に約7年)</li><li>OpenGLは拡張機構で追随するも、ARB (委員会) の意思決定の遅さで徐々に後退。<strong>OpenGL 3.0 (2008) の「旧API破棄」公約が骨抜きになった事件</strong>でゲーム業界の信頼を失う</li><li>DX10 (2006): API完全再設計 (ステートオブジェクト化、固定機能撤廃) だがVista専用で普及が遅れた</li><li>この時代の教訓: <strong>後方互換の呪縛</strong> — 古い設計を捨てられないAPIは性能の天井に達する</li></ul><h2 id="第3期-ドローコール危機と明示的api革命-2009〜2016" tabindex="-1">第3期: ドローコール危機と明示的API革命 (2009〜2016) <a class="header-anchor" href="#第3期-ドローコール危機と明示的api革命-2009〜2016" aria-label="Permalink to &quot;第3期: ドローコール危機と明示的API革命 (2009〜2016)&quot;">​</a></h2><h3 id="当時の課題" tabindex="-1">当時の課題 <a class="header-anchor" href="#当時の課題" aria-label="Permalink to &quot;当時の課題&quot;">​</a></h3><p>DX11/GL時代のドライバは:</p><ol><li><strong>隠れた状態検証</strong>: ドローごとに全ステートの整合性をチェック</li><li><strong>隠れたリソース追跡</strong>: ハザード (書き込み中のテクスチャを読む等) をドライバが推測して自動でバリア挿入</li><li><strong>シングルスレッド前提</strong>: コンテキストが1本で、マルチコアCPUを活かせない</li><li><strong>シェーダの遅延コンパイル</strong>: ドロー時にステート組み合わせが確定してから最終コンパイル → ヒッチ</li></ol><p>結果、CPU1コアだけが忙殺され、ドローコールは数千/フレームで頭打ちでした。</p><h3 id="mantle革命" tabindex="-1">Mantle革命 <a class="header-anchor" href="#mantle革命" aria-label="Permalink to &quot;Mantle革命&quot;">​</a></h3><p>2013年、AMDとDICE (Battlefield 4) が <strong>Mantle</strong> を発表。「ドライバの仕事をアプリに移す」設計 — コマンドバッファの明示的記録、PSO、手動ハザード管理、明示的メモリ管理 — でドローコールコストを1桁削減しました。</p><ul><li>2014: Apple <strong>Metal</strong> (同思想をモバイルへ)</li><li>2015: <strong>DirectX 12</strong> (Windows 10)</li><li>2016: <strong>Vulkan 1.0</strong> — MantleがKhronosに寄贈され、そのまま土台に</li></ul>',12)),(e(),i(o,null,{default:t(()=>[n(l,{id:"mermaid-135",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20%E6%97%A7API%5B%22%E6%97%A7API%20(GL%2FDX11)%22%5D%0A%20%20%20%20%20%20%20%20A1%5B%E3%82%A2%E3%83%97%E3%83%AA%3A%20%E6%8F%8F%E7%94%BB%E6%84%8F%E5%9B%B3%5D%20--%3E%20D1%5B%22%E3%83%89%E3%83%A9%E3%82%A4%E3%83%90%3A%3Cbr%2F%3E%E6%A4%9C%E8%A8%BC%E3%83%BB%E8%BF%BD%E8%B7%A1%E3%83%BB%E5%90%8C%E6%9C%9F%E3%83%BB%E3%82%B3%E3%83%B3%E3%83%91%E3%82%A4%E3%83%AB%3Cbr%2F%3E(%E3%83%96%E3%83%A9%E3%83%83%E3%82%AF%E3%83%9C%E3%83%83%E3%82%AF%E3%82%B9%E3%83%BB1%E3%82%B9%E3%83%AC%E3%83%83%E3%83%89)%22%5D%20--%3E%20G1%5BGPU%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20%E6%96%B0API%5B%22%E6%98%8E%E7%A4%BA%E7%9A%84API%20(DX12%2FVK%2FMetal)%22%5D%0A%20%20%20%20%20%20%20%20A2%5B%22%E3%82%A2%E3%83%97%E3%83%AA%3A%3Cbr%2F%3EPSO%E4%BA%8B%E5%89%8D%E6%A7%8B%E7%AF%89%E3%83%BB%E3%83%90%E3%83%AA%E3%82%A2%E6%98%8E%E7%A4%BA%E3%83%BB%3Cbr%2F%3E%E3%83%9E%E3%83%AB%E3%83%81%E3%82%B9%E3%83%AC%E3%83%83%E3%83%89%E8%A8%98%E9%8C%B2%E3%83%BB%E3%83%A1%E3%83%A2%E3%83%AA%E7%AE%A1%E7%90%86%22%5D%20--%3E%20D2%5B%22%E3%83%89%E3%83%A9%E3%82%A4%E3%83%90%3A%20%E8%96%84%E3%81%84%E5%A4%89%E6%8F%9B%E5%B1%A4%22%5D%20--%3E%20G2%5BGPU%5D%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="第4期-機能拡張と収斂-2017〜現在" tabindex="-1">第4期: 機能拡張と収斂 (2017〜現在) <a class="header-anchor" href="#第4期-機能拡張と収斂-2017〜現在" aria-label="Permalink to &quot;第4期: 機能拡張と収斂 (2017〜現在)&quot;">​</a></h2><ul><li>2018: <strong>DXR</strong> (レイトレーシング) → Vulkan Ray Tracing (2020) → <a href="/study/graphics/lighting/raytracing.html">レイトレーシング</a></li><li>2018-20: Mesh Shader、Variable Rate Shading (DX12 Ultimate / VK拡張)</li><li>2023: <strong>WebGPU</strong> — 明示的API世代の設計をWeb安全性の制約下で再蒸留した「4番目のAPI」</li><li>2024-: <strong>Work Graphs</strong> (GPU自律的なワーク生成)、バインドレス常態化、Descriptor Buffer等 — 「GPUが自分で描画を組み立てる」方向へ</li><li>同時に、明示的APIの複雑さへの反省から<strong>簡素化の揺り戻し</strong> (VK: Dynamic Rendering, Shader Object拡張) も進行中</li></ul><h2 id="それ以前の技術-解決した課題-現在の位置づけ-総括" tabindex="-1">それ以前の技術 / 解決した課題 / 現在の位置づけ (総括) <a class="header-anchor" href="#それ以前の技術-解決した課題-現在の位置づけ-総括" aria-label="Permalink to &quot;それ以前の技術 / 解決した課題 / 現在の位置づけ (総括)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>世代</th><th>代表</th><th>解決した課題</th><th>生んだ課題</th></tr></thead><tbody><tr><td>即時モード</td><td>GL 1.x</td><td>ハードウェア差の抽象化</td><td>呼び出しオーバーヘッド</td></tr><tr><td>ステートマシン+VBO</td><td>GL 2-4 / DX9</td><td>データのGPU常駐化</td><td>ドライバの隠れコスト</td></tr><tr><td>ステートオブジェクト</td><td>DX10/11</td><td>状態変更の整理</td><td>1スレッド制約は残存</td></tr><tr><td>明示的API</td><td>DX12/VK/Metal</td><td>CPUボトルネック・マルチコア活用</td><td>アプリ側の複雑さ激増</td></tr><tr><td>Web標準</td><td>WebGPU</td><td>安全性と移植性の両立</td><td>機能の最大公約数化</td></tr></tbody></table><h2 id="各環境での扱い" tabindex="-1">各環境での扱い <a class="header-anchor" href="#各環境での扱い" aria-label="Permalink to &quot;各環境での扱い&quot;">​</a></h2><h3 id="unity" tabindex="-1">Unity <a class="header-anchor" href="#unity" aria-label="Permalink to &quot;Unity&quot;">​</a></h3><p>Graphics API設定で DX11/DX12/Vulkan/Metal/GLES を選択可能。エンジンが差を吸収するため、この歴史は「なぜUnityのAPIがこう設計されているか」(CommandBuffer、SRP Batcher等) の背景知識になります。</p><h3 id="unreal-engine" tabindex="-1">Unreal Engine <a class="header-anchor" href="#unreal-engine" aria-label="Permalink to &quot;Unreal Engine&quot;">​</a></h3><p>RHI層が全APIを抽象化。UE5はDX12/Vulkan/Metalが主要ターゲットで、DX11は縮小方向。RHIの設計自体が「明示的API世代の共通形」を反映しています。</p><h3 id="directx-12-vulkan" tabindex="-1">DirectX 12 / Vulkan <a class="header-anchor" href="#directx-12-vulkan" aria-label="Permalink to &quot;DirectX 12 / Vulkan&quot;">​</a></h3><p>本章の主役。それぞれ <a href="/study/graphics/api/directx12.html">DirectX 12</a>、<a href="/study/graphics/api/vulkan.html">Vulkan</a> で詳解します。</p><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><ul><li><a href="/study/hardware/gpu/cpu-vs-gpu.html">CPUとGPUの役割分担</a></li></ul><h2 id="次に読むべきページ" tabindex="-1">次に読むべきページ <a class="header-anchor" href="#次に読むべきページ" aria-label="Permalink to &quot;次に読むべきページ&quot;">​</a></h2><ul><li><a href="/study/graphics/api/opengl.html">OpenGL</a> — 旧世代の設計を知る</li><li><a href="/study/graphics/api/directx11.html">DirectX 11</a> — 過渡期の到達点</li><li><a href="/study/graphics/api/directx12.html">DirectX 12</a> / <a href="/study/graphics/api/vulkan.html">Vulkan</a> — 現代の主役</li><li><a href="/study/graphics/api/comparison.html">4大API横断比較</a></li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p><strong>DX11世代のドライバが行っていた「隠れた仕事」を3つ挙げ、DX12/Vulkanではそれぞれ誰の責務になったか述べよ。</strong></p><details class="details custom-block"><summary>解答</summary><p>(1)状態検証→PSO作成時に前倒しされアプリが正しい組み合わせを保証。(2)リソースハザードの自動追跡と同期→アプリが明示的にバリア/フェンスを記述。(3)メモリ割り当てと常駐管理→アプリがヒープを確保しサブアロケーションを管理。いずれも「毎ドローの隠れコスト」を「アプリ設計時の明示コスト」に変換した。</p></details></li><li><p><strong>Mantleが歴史的に重要である理由を、単なる「速いAPI」以上の観点で説明せよ。</strong></p><details class="details custom-block"><summary>解答</summary><p>明示的API設計が実ゲーム(BF4)で劇的なCPU削減を実証し、業界全体の設計転換を引き起こした。さらに仕様自体がKhronosへ寄贈されVulkanの直接の土台となり、DX12/Metalの設計にも強い影響を与えた。「一社の実験が全APIの世代交代を駆動した」稀有な例。</p></details></li><li><p><strong>WebGPUが「4番目の明示的API」として、DX12/VK/Metalと異なる制約下で設計された点は何か。</strong></p><details class="details custom-block"><summary>解答</summary><p>悪意あるコードの実行を前提とするWebサンドボックスでの動作。全リソースアクセスの検証可能性、未定義動作の排除、3つのネイティブAPIすべての上で実装可能な最大公約数的機能セット、という制約の下で明示的API設計を再構成している。</p></details></li></ol><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li>Fabien Sanglard, 各種 &quot;Game Engine Black Book&quot; とAPI史記事</li><li>GDC Vault: <em>Mantle</em> (2014), <em>DX12 &amp; Vulkan: Lessons Learned</em> 系講演</li><li>Khronos, <em>Vulkan: The Origin Story</em> / Alex St. John らのDirectX創世記の回顧録</li><li>retro-computing系: OpenGL vs Direct3D 論争のアーカイブ (Carmack .plan files)</li></ul>',19))])}const b=A(h,[["render",u]]);export{D as __pageData,b as default};
